// ============================================
// VALIDATION INPUT - Quiz Generator
// ============================================

const input = $input.first().json;
const body = input.body || input;

// Support RFC-014: data in context.* with fallback to root level
const ctx = body.context || {};

const errors = [];

// --- Required context fields ---
const userId = body.user_id || ctx.user_id;
const guildId = body.guild_id || ctx.guild_id;
const userRequest = body.user_request || ctx.user_request;

if (!userId) {
  errors.push('user_id requis');
}
if (!guildId) {
  errors.push('guild_id requis');
}
if (!userRequest) {
  errors.push('user_request requis');
}

// --- Specific webhook parameters ---
const data = body.data || ctx.data || null;
const source = body.source || ctx.source || 'text';
const options = body.options || ctx.options || {};

// Validate required data parameter
if (!data) {
  errors.push('data requis (texte, sujet ou URL)');
}

// Validate source enum
if (!['text', 'topic', 'url'].includes(source)) {
  errors.push('source doit etre text, topic ou url');
}

// Parse options with defaults
const numQuestions = options.num_questions || 10;
const questionTypes = options.question_types || ['multiple_choice', 'true_false'];
const difficulty = options.difficulty || 'medium';
const language = options.language || 'fr';
const includeExplanations = options.include_explanations !== false;

// Validate difficulty enum
if (!['easy', 'medium', 'hard'].includes(difficulty)) {
  errors.push('difficulty doit etre easy, medium ou hard');
}

// --- API Keys passed from MCP Server ---
const openaiApiKey = body.openai_api_key || ctx.openai_api_key || body.plugin_context?.api_keys?.openai || '';
const model = body.model || ctx.model || 'gpt-4o';

if (!openaiApiKey) {
  errors.push('openai_api_key requis');
}

if (errors.length > 0) {
  return {
    valid: false,
    errors: errors,
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest
  };
}

return {
  valid: true,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest,
  data: data,
  source: source,
  num_questions: numQuestions,
  question_types: questionTypes,
  difficulty: difficulty,
  language: language,
  include_explanations: includeExplanations,
  openaiApiKey: openaiApiKey,
  model: model,
  startTime: Date.now()
};

// ============================================
// BUILD VALIDATION ERROR
// ============================================

const input = $input.first().json;

return {
  success: false,
  _trace: {
    service_response: { validation_errors: input.errors },
    provider: 'none',
    mode: 'error',
    latency_ms: 0,
    user_id: input.user_id,
    guild_id: input.guild_id,
    user_request: input.user_request
  },
  error: {
    code: 'VALIDATION_ERROR',
    message: input.errors.join(', '),
    http_status: 400
  },
  user_id: input.user_id,
  guild_id: input.guild_id,
  user_request: input.user_request
};

