// ============================================
// PARSE LLM RESPONSE - Quiz Generator
// ============================================

const input = $input.first().json;
const prevData = $('Validate Input').first().json;
const startTime = prevData.startTime || Date.now();

// --- Context fields for traceability ---
const userId = prevData.user_id;
const guildId = prevData.guild_id;
const userRequest = prevData.user_request;

const statusCode = input.statusCode || 200;

// Initialize trace with llm_response format
const _trace = {
  llm_response: null,
  service_response: null,
  provider: 'openai',
  model: prevData.model || 'gpt-4o',
  tokens: { input: 0, output: 0 },
  latency_ms: 0,
  user_id: userId,
  guild_id: guildId,
  user_request: userRequest
};

// Handle API error
if (statusCode >= 400 || input.error) {
  const errorMsg = input.body?.error?.message || input.error?.message || 'OpenAI API error';
  _trace.llm_response = `Error: ${errorMsg}`;
  _trace.service_response = input.body || input;
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'LLM_ERROR',
        message: errorMsg,
        http_status: statusCode
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract response
const body = input.body || input;
const content = body.choices?.[0]?.message?.content || '';
const usage = body.usage || {};

// Populate trace with LLM response
_trace.llm_response = content;
_trace.service_response = body;
_trace.tokens = {
  input: usage.prompt_tokens || 0,
  output: usage.completion_tokens || 0
};

// Parse JSON from response
let parsed;
try {
  // Handle markdown code blocks
  let jsonStr = content;
  const codeBlockMatch = content.match(/```(?:json)?\s*([\s\S]*?)```/);
  if (codeBlockMatch) {
    jsonStr = codeBlockMatch[1].trim();
  } else {
    const rawMatch = content.match(/\{[\s\S]*\}/);
    if (rawMatch) jsonStr = rawMatch[0];
  }

  parsed = JSON.parse(jsonStr);
} catch (e) {
  _trace.latency_ms = Date.now() - startTime;

  return {
    json: {
      success: false,
      error: {
        code: 'PARSE_ERROR',
        message: 'Failed to parse quiz response: ' + e.message,
        http_status: 500
      },
      user_id: userId,
      guild_id: guildId,
      user_request: userRequest,
      _trace: _trace
    }
  };
}

// Extract quiz data
const quiz = parsed.quiz || parsed;

_trace.latency_ms = Date.now() - startTime;

return {
  json: {
    success: true,
    data: quiz,
    meta: {
      provider: 'openai',
      model: prevData.model || 'gpt-4o',
      source: prevData.source,
      difficulty: prevData.difficulty,
      language: prevData.language,
      tokens_used: (usage.prompt_tokens || 0) + (usage.completion_tokens || 0),
      processing_time_ms: Date.now() - startTime
    },
    user_id: userId,
    guild_id: guildId,
    user_request: userRequest,
    _trace: _trace
  }
};

